let x = Math.max(...page.children.map((n) => n.x + n.width)) + 400
for (const s of [...screensOf.values()].slice(0, 6)) { const c = s.clone(); page.appendChild(c); c.x = x; c.y = 0; x += c.width + 100; await keepModes(c, s); clones.push(c) }
